def pgcd_etendu(a, b):
    """Retourne (g, u, v) tel que g = pgcd(a,b) et a*u + b*v = g."""
    if b == 0:
        return (a, 1, 0)
    else:
        g, u1, v1 = pgcd_etendu(b, a % b)
        u = v1
        v = u1 - (a // b) * v1
        return (g, u, v)

# Exemple
print(pgcd_etendu(252, 198))  # (18, -4, 5) car 252*(-4) + 198*5 = 18

def bezout(a, b):
    """Retourne (g, u, v) avec g = pgcd(a,b) et a*u + b*v = g."""
    if b == 0:
        return (a, 1, 0)
    else:
        g, u1, v1 = bezout(b, a % b)
        u = v1
        v = u1 - (a // b) * v1
        return (g, u, v)

print(bezout(56, 15))  # (1, 4, -15)
